mapper.select:
SELECT ${groupParam} as key_name,COUNT(e.id) AS total_num
FROM ods_tims_realtime_event e
LEFT JOIN ods_tims_dt_road r on r.id = e.road
LEFT JOIN ods_tims_dt_department d on d.id = e.department

    
    
        ${whereAppend}
    

GROUP BY ${groupParam}

    
        ORDER BY ${orderParam}
    
    
        ORDER BY total_num desc
    

 LIMIT #{limitSize}
